class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        unordered_map<int,int> seen;
        seen[0] = -1;
        int sum = 0, best = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            sum += nums[i] ? 1 : -1;
            auto it = seen.find(sum);
            if (it != seen.end()) {
                int len = i - it->second;
                if (len > best) best = len;
            } else {
                seen[sum] = i;
            }
        }
        return best;
    }
};
